import sys

PREC = {"+": 1, "-": 1, "*": 2, "/": 2, "^": 3}

def tokenize(text):
    tokens = []
    number = ""
    for ch in text:
        if ch.isdigit():
            number += ch
            continue
        if number:
            tokens.append(int(number))
            number = ""
        if ch in PREC or ch in "()":
            tokens.append(ch)
    if number:
        tokens.append(int(number))
    return tokens

def apply(op, b, a):
    if op == "+":
        return a + b
    if op == "-":
        return a - b
    if op == "*":
        return a * b
    if op == "/":
        return a // b
    if op == "^":
        return a ** b

def evaluate(tokens):
    values, ops = [], []

    def reduce():
        if not ops:
            raise ValueError("Invalid expression")
        op = ops.pop()
        b = values.pop()
        a = values.pop()
        values.append(apply(op, b, a))

    for tok in tokens:
        if isinstance(tok, int):
            values.append(tok)
        elif tok == "(":
            ops.append(tok)
        elif tok == ")":
            while ops[-1] != "(":
                try:
                    reduce()
                except:
                    return "error"
            ops.pop()
        else:
            while ops and ops[-1] != "(" and PREC[ops[-1]] >= PREC[tok]:
                try:
                    reduce()
                except:
                    return "error"
            ops.append(tok)
    while ops:
        try:
            reduce()
        except ZeroDivisionError:
            return "error"
        except:
            return "error"
    return values[0]

def main():
    for line in sys.stdin:
        line = line.strip()
        if line:
            try:
                result = evaluate(tokenize(line))
                print(result)
            except ZeroDivisionError:
                print("error")
            except:
                print("error")

if __name__ == "__main__":
    main()
